mapper.select:
SELECT c.id, c.complaint_type, CASE c.complaint_type WHEN 1 THEN '学生投诉企业' WHEN 2 THEN '企业投诉学生' ELSE '未知' END AS complaint_type_name, c.complainer_id, CASE c.complainer_type WHEN 1 THEN s1.nick_name WHEN 2 THEN e1.enterprise_name ELSE '未知' END AS complainer_name, c.complained_id, CASE c.complained_type WHEN 1 THEN s2.nick_name WHEN 2 THEN e2.enterprise_name ELSE '未知' END AS complained_name, c.title, c.content, c.handle_status, CASE c.handle_status WHEN 0 THEN '待处理' WHEN 1 THEN '处理中' WHEN 2 THEN '已处理' WHEN 3 THEN '已关闭' ELSE '未知' END AS handle_status_name, c.create_time FROM complaint c LEFT JOIN student s1 ON c.complainer_type = 1 AND c.complainer_id = s1.id LEFT JOIN enterprise e1 ON c.complainer_type = 2 AND c.complainer_id = e1.id LEFT JOIN student s2 ON c.complained_type = 1 AND c.complained_id = s2.id LEFT JOIN enterprise e2 ON c.complained_type = 2 AND c.complained_id = e2.id
AND c.handle_status = #{handleStatus}
AND c.complaint_type = #{complaintType}
ORDER BY c.create_time DESC
